// Test-only reconstruction of the public HomeModal/NpcModal structure.
// No downloaded game JavaScript is executed and no real account is used.
import fs from 'node:fs';
export const gameCSS=fs.readFileSync(new URL('./home-expanded-game.css',import.meta.url),'utf8');
export const fixtureHTML=`<!doctype html><html lang="hu"><meta charset="utf-8"><title>Otthon – helyi addon próba</title>
<link rel="stylesheet" href="/fixture/game.css"><style>
html,body{margin:0;min-height:100%;background:#11191b;color:#f4e2b5;font-family:system-ui}
.fixture-status{position:fixed;left:20px;bottom:1px;z-index:3000;padding:4px 9px;background:#102023e8;color:#c9ccbd;border:1px solid #7d693b;font:12px system-ui;pointer-events:none}
.fixture-open{margin:30px}.fixture-game .h2-house{display:grid;gap:10px}.fixture-game .h2-level,.fixture-game .h2-daily,.fixture-game .h2-milestones{padding:12px;border:1px solid #92733f;border-radius:10px;background:#312a20}.fixture-game .h2-level{display:flex;gap:14px;align-items:center}.fixture-game .h2-level__badge{font:42px Georgia;color:#efc879}.fixture-game .h2-house h3,.fixture-game .h2-house p{margin:4px 0}.fixture-game .h2-daily label{display:block;font-size:14px;line-height:1.8}.fixture-game .home-house{display:grid;gap:12px}.fixture-game .home-house h3{margin:4px 0}.fixture-game .home-card__text{padding:5px}.fixture-game .home-card .home-art{width:100px}.fixture-game .home-card img{width:100%}.fixture-game .home-next{padding:12px}.fixture-game .home-gives{padding:12px}.fixture-game .home-ladder{margin:0}.fixture-game .fixture-submodal{z-index:2000}.fixture-game .fixture-submodal .npc-modal__dialog{width:min(440px,calc(100% - 32px));height:auto;max-height:90vh;padding:0}.fixture-game .fixture-submodal .npc-modal__body{padding:20px}.fixture-game .fixture-submodal .npc-modal__head{padding:18px 60px 18px 20px}.fixture-game .fixture-room-empty{padding:25px}.fixture-game .home-room .fixture-room-piece{min-width:0}.fixture-game .npc-modal__portrait img{width:100%}.fixture-game .home-furnish .furn-offer{min-width:0}.fixture-game .fixture-ranking{width:100%;border-collapse:collapse}.fixture-game .fixture-ranking td,.fixture-game .fixture-ranking th{padding:16px;text-align:left;border-bottom:1px solid #80643b}
</style><body class="fixture-game"><button class="fixture-open" type="button">Otthon megnyitása</button><span class="fixture-status">HELYI TESZT • nyilvános kliensstruktúra, mintadatok</span><script>
(()=>{
const asset=id=>'/fixture/art/'+id+'.webp';
const img=(id,cls='')=>'<img class="'+cls+'" src="'+asset(id)+'" alt="">';
const tabs=[['house','Ház'],['furnish','Berendezés'],['trophies','Trófeák'],['rooms','Szobák'],['ranking','Rangsor'],['jar','Persely']];
const room=()=>'<div class="home-room home-room--house home-stage">'+img('scenes/home_house','home-room__bg art--scenes')+'<button type="button" class="home-room__piece is-floor fixture-room-piece" data-original="furniture" style="left:38%;top:80%;width:20%">'+img('furniture/furrug','home-room__img art')+'</button><button type="button" class="home-room__piece fixture-room-piece" data-original="trophy" style="left:68%;top:40%;width:7%">'+img('furniture/goldcup','home-room__img art')+'</button><button type="button" class="home-room__slot" data-original="slot" style="left:72%;top:82%;width:8%"><span class="home-room__plus"></span></button></div>';
const house=()=>'<div class="home-house"><div class="h2-house" data-home2="house"><section class="h2-level"><span class="h2-level__badge">24</span><div><p>OTTHON-SZINT</p><h3>Otthon, édes otthon</h3><p>320 / 500 fejlődési pont</p></div></section><section class="h2-daily"><h3>Mai teendők</h3><label><input type="checkbox" data-original="task"> Szobajutalom begyűjtése</label><label><input type="checkbox"> Bútor elhelyezése</label><label><input type="checkbox"> Az otthon fejlesztése</label></section><section class="h2-milestones"><h3>Mérföldkövek</h3><p>Következő jutalom a 25. otthonszinten.</p><progress value="24" max="25"></progress></section></div><section class="home-card"><div class="home-house__scene"><span class="home-art">'+img('scenes/home_house')+'</span></div><div class="home-card__text"><p class="home-card__tier">HÁZFOK: 4 / 8</p><h3>Berendezett ház</h3><p>A bútorok és trófeák a szobában maradnak.</p></div></section><section class="home-gives"><h3>Bónuszok</h3><p>Energiatárolás, pihenés és berendezési előnyök</p><button type="button" data-original="bonus">Részletek</button><p class="fixture-bonus" hidden>A bónuszok eredeti részletezője.</p></section><section class="home-next"><h3>Következő házfok</h3><p>Tágas otthon · szintkövetelmény és fejlesztési költség</p><button class="btn" type="button" data-original="upgrade">Házfejlesztés</button></section><ol class="home-ladder">'+Array.from({length:8},(_,i)=>'<li class="home-ladder__step '+(i<4?'is-done':'')+'"><span class="home-ladder__pip">'+(i+1)+'</span></li>').join('')+'</ol><p class="sink-foot">Naponta egy házfok fejleszthető.</p></div>';
const cards=(cls,count)=>'<div class="'+cls+'">'+Array.from({length:count},(_,i)=>'<article class="furn-offer"><span class="furn-icon">'+img('icons/furn_'+(['furrug','goldcup','calligraphy','floursack'][i%4]),'furn-icon__img')+'</span><strong class="furn-offer__name">'+(['Szőrmeszőnyeg','Aranyserleg','Kalligrafikus tekercs','Lisztzsák'][i%4])+'</strong><p class="furn-offer__meta">Eredeti bútorkártya · '+(i+1)+'</p><button type="button" class="btn" data-original="offer">Megtekintés</button></article>').join('')+'</div>';
const content={house:()=>room()+house(),furnish:()=>room()+'<div class="home-furnish"><section class="home-comfort"><h3>Kényelem és berendezés</h3></section><section class="furn-shop"><h3>Bútorok</h3>'+cards('furn-offers',24)+'</section><section class="home-storage"><h3>Raktár</h3><p>Az eredeti tárolt bútorok listája.</p></section></div>',trophies:()=>'<div class="home-trophies"><h3>Trófeák</h3>'+cards('trophy-options',12)+'</div>',rooms:()=>'<div class="home-rooms"><h3>Szobák</h3><div class="home-rooms__grid">'+['Pihenő','Műhely','Csarnok','Kert'].map(x=>'<section class="home-card"><h3>'+x+'</h3><p>Szobafejlesztés és jutalom</p><button type="button" data-original="room">Részletek</button></section>').join('')+'</div></div>',ranking:()=>'<section><h3>Otthon rangsor</h3><table class="fixture-ranking"><thead><tr><th>Helyezés</th><th>Otthon</th><th>Szint</th></tr></thead><tbody>'+Array.from({length:30},(_,i)=>'<tr><td>'+(i+1)+'</td><td>Helyi mintasor</td><td>'+(50-i)+'</td></tr>').join('')+'</tbody></table></section>',jar:()=>'<section class="home-jar"><h3>Persely</h3><div class="jar-pot"><p>Félretett pénz – helyi minta</p></div><div class="jar-move"><label>Összeg <input aria-label="Persely összeg" type="number" value="10"></label><button type="button" data-original="jar">Részletek</button></div><p>A próba nem hajt végre befizetést.</p></section>'};
let modal,active='house',clicks={};
function confirm(){const div=document.createElement('div');div.className='modal npc-modal fixture-submodal';div.innerHTML='<div class="npc-modal__dialog" role="dialog" aria-label="Helyi megerősítés"><button class="modal__close" aria-label="Megerősítés bezárása" type="button">×</button><header class="npc-modal__head"><h2>Megerősítés</h2></header><div class="npc-modal__body"><p>Ez helyi kezelőelem-próba. Nem történik fejlesztés vagy vásárlás.</p><button type="button" data-cancel>Mégse</button></div></div>';div.addEventListener('click',e=>{if(e.target.closest('.modal__close,[data-cancel]'))div.remove();});document.body.append(div);}
function select(tab){active=tab;for(const b of modal.querySelectorAll('[data-home-tab]')){b.setAttribute('aria-selected',String(b.dataset.homeTab===tab));b.classList.toggle('is-active',b.dataset.homeTab===tab);}const panel=modal.querySelector('.sink-panel');panel.className='sink-panel'+(tab==='furnish'?' sink-panel--furnish':'');panel.innerHTML=content[tab]();panel.scrollTop=0;}
function open(){if(modal?.isConnected)return;modal=document.createElement('div');modal.className='modal npc-modal npc-modal--scene';modal.innerHTML='<div class="npc-modal__scene-box" aria-hidden="true">'+img('scenes/int_home','npc-modal__scene')+'</div><div class="npc-modal__dialog panel qpanel sink-modal home-modal" data-tut-screen="home" role="dialog" aria-label="Otthon" aria-modal="true" tabindex="-1"><button type="button" class="modal__close" aria-label="Otthon bezárása">×</button><header class="npc-modal__head has-purse"><span class="npc-modal__portrait">'+img('icons/furn_goldcup')+'</span><div class="npc-modal__intro"><h2 class="npc-modal__title ink-title">Otthon</h2><p class="npc-modal__line">A saját zugod a viharban.</p></div><div class="npc-modal__purse"><span class="chip">12 500</span></div></header><div class="npc-modal__body"><div class="tabs sink-tabs" role="tablist">'+tabs.map(([id,label])=>'<button type="button" class="tabs__tab" role="tab" data-home-tab="'+id+'">'+label+'</button>').join('')+'</div><div class="sink-panel" role="tabpanel"></div></div></div>';modal.addEventListener('click',e=>{if(e.target===modal||e.target.closest('.modal__close')){modal.remove();return;}const tab=e.target.closest('[data-home-tab]');if(tab){select(tab.dataset.homeTab);return;}const button=e.target.closest('[data-original]');if(button){clicks[button.dataset.original]=(clicks[button.dataset.original]??0)+1;if(['upgrade','furniture','trophy','slot','offer','room','jar'].includes(button.dataset.original))confirm();if(button.dataset.original==='bonus'){const p=modal.querySelector('.fixture-bonus');p.hidden=!p.hidden;}}});document.body.append(modal);select(active);}
document.querySelector('.fixture-open').onclick=open;document.addEventListener('keydown',e=>{if(e.key==='Escape'){const sub=document.querySelector('.fixture-submodal');if(sub)sub.remove();else modal?.remove();}});window.__homeFixture={open,select,clicks,rerender(){select(active);},replace(){modal.remove();open();}};open();
})();</script></body></html>`;
